 return <form className="f-form" onSubmit={e=>{e.preventDefault();if(apply({type:"recommend",clientId:id,propertyIds:ps,content,nextAt:next}))onDone();}}><Field label="关联客户 *"><select required value={id} onChange={e=>setId(e.target.value)}><option value="">请选择客户</option>{eligible.map(c=><option key={c.id} value={c.id}>{c.name} · {c.phone}</option>)}</select></Field>{c&&<div className="f-context"><b>{c.area} · {c.budget} 元/月</b><small>按客户需求选择房源，支持多选；不会自动向外发送消息。</small></div>}<div className="f-property-choices">{s.properties.filter(p=>p.status==="可租").map(p=><label key={p.id}><input type="checkbox" checked={ps.includes(p.id)} onChange={()=>setPs(ps.includes(p.id)?ps.filter(x=>x!==p.id):[...ps,p.id])}/><div><b>{p.name}</b><small>{p.area} · {p.rooms}</small></div><strong>{money(p.rent)}/月</strong></label>)}</div><Field label="推荐备注"><textarea value={content} onChange={e=>setContent(e.target.value)} placeholder="记录匹配理由和沟通情况"/></Field><Field label="反馈跟进时间 *"><input type="datetime-local" required min={future(.02)} value={next} onInput={e=>setNext(e.currentTarget.value)}/></Field><div className="f-form-footer"><span>{ps.length} 套已选</span><button className="f-primary" disabled={!eligible.length||!ps.length}>保存推荐并安排反馈</button></div></form>;
